INSERT INTO DimBroker (SK_BrokerID, BrokerID, ManagerID, FirstName, LastName, MiddleInitial, Branch, Office, Phone, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT ROW_NUMBER() OVER (ORDER BY EmployeeID) AS SK_BrokerID, EmployeeID AS BrokerID, ManagerID, EmployeeFirstName AS FirstName, EmployeeLastName AS LastName, EmployeeMI AS MiddleInitial, EmployeeBranch AS Branch, EmployeeOffice AS Office, EmployeePhone AS Phone, TRUE AS IsCurrent, 1 AS BatchID, (SELECT MIN(DateValue) FROM DimDate) AS EffectiveDate, CAST('9999-12-31' AS DATE) AS EndDate FROM Source.HR WHERE EmployeeJobCode = 314